package com.anthony6996.hardcorecompass.listener;
import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.manager.CompassManager;import org.bukkit.Sound;import org.bukkit.block.Block;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.ItemStack;
public final class LodestoneListener implements Listener{
 private final CompassManager compasses;private final ConfigManager config;public LodestoneListener(CompassManager c,ConfigManager cfg){compasses=c;config=cfg;}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void onPlace(BlockPlaceEvent e){if(compasses.isHardcoreLodestone(e.getItemInHand()))compasses.markPlacedLodestone(e.getBlockPlaced(),e.getPlayer().getUniqueId());}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onInteract(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||e.getClickedBlock()==null||!e.getAction().isRightClick()||!compasses.isHardcoreLodestoneBlock(e.getClickedBlock()))return;Player p=e.getPlayer();ItemStack hand=p.getInventory().getItemInMainHand();if(!compasses.isHardcoreCompass(hand))return;Block block=e.getClickedBlock();compasses.bind(hand,p,block.getLocation());p.getInventory().setItemInMainHand(hand);p.playSound(block.getLocation(),Sound.ITEM_LODESTONE_COMPASS_LOCK,1f,1f);p.sendMessage(config.getMessage(p,"compass-bound"));}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void onBreak(BlockBreakEvent e){Block b=e.getBlock();if(!compasses.isHardcoreLodestoneBlock(b))return;Player p=e.getPlayer();if(!compasses.mayBreak(b,p)){e.setCancelled(true);p.sendMessage(config.getMessage(p,"lodestone-break-denied"));return;}if(config.untrackOnLodestoneBreak())compasses.markTargetLost(b.getWorld(),b.getLocation());}
}
